import ezdxf
import math

doc = ezdxf.readfile('project/drawings/E-611_level_1_power_plan.dxf')
msp = doc.modelspace()

# Measure each routing layer
for layer_name in ['E-RTE-B-01', 'E-RTE-B-02', 'E-RTE-B-04', 'E-RTE-B-07', 'E-RTE-B-08', 'E-RTE-B-09', 'E-RTE-B-10', 'E-RTE-B-11', 'E-RTE-B-12', 'E-RTE-B-13', 'E-RTE-B-14', 'E-RTE-B-15', 'E-RTE-F-01', 'E-RTE-F-03', 'E-RTE-F-11']:
    total_len = 0
    for e in msp:
        if e.dxf.layer == layer_name:
            if e.dxftype() == 'LWPOLYLINE':
                points = list(e.get_points())
                for i in range(len(points)-1):
                    dx = points[i+1][0] - points[i][0]
                    dy = points[i+1][1] - points[i][1]
                    total_len += math.sqrt(dx*dx + dy*dy)
            elif e.dxftype() == 'LINE':
                dx = e.dxf.end.x - e.dxf.start.x
                dy = e.dxf.end.y - e.dxf.start.y
                total_len += math.sqrt(dx*dx + dy*dy)
    if total_len > 0:
        print(f'{layer_name}: {total_len:.1f} ft')
"

